"""Managed-source integration: generated bytes only, no cookies or network."""

import asyncio
from dataclasses import replace
from io import BytesIO
import json
from threading import Event

from PIL import Image
import pytest

from pixivvault_nicegui.bootstrap import main, parse_args
from pixivvault_nicegui.services import ApplicationServices


def png(color):
    result = BytesIO()
    Image.new("RGB", (80, 64), color).save(result, "PNG")
    return result.getvalue()


class FakeSource:
    def __init__(self):
        self.closed = False
        self.calls = []
        self.fail = False
        self.fail_images = False
        self.started = Event()
        self.gate = None

    def verify_identity(self):
        self.calls.append("identity")
        return "12"

    def get_bookmarked_works(self, identity, rest_type):
        assert identity == "12"
        self.calls.append(("bookmarks", rest_type))
        if rest_type == "show":
            yield {"id": "202", "title": "合成原寸作品", "user_id": "23",
                   "user_name": "合成作者", "tags": ["original"], "type": 0,
                   "thumb_url": "https://i.pximg.net/synthetic/202.png", "page_count": 2}
            yield {"id": "203", "title": "合成うごイラ", "user_id": "23",
                   "user_name": "合成作者", "tags": [], "type": 2,
                   "thumb_url": "https://i.pximg.net/synthetic/203.png", "page_count": 1}

    def get_bookmarked_novels(self, identity, rest_type):
        self.calls.append(("novels", rest_type))
        if self.fail and rest_type == "hide":
            raise OSError("synthetic private failure text")
        return iter(())

    def get_artwork_original_pages(self, work_id):
        assert work_id == "202"
        self.calls.append("original-pages")
        return tuple(f"https://i.pximg.net/img-original/img/2026/10/01/12/00/00/202_p{i}.png"
                     for i in range(2))

    def get_artwork_pages(self, work_id):
        self.calls.append("regular-pages")
        return tuple(f"https://i.pximg.net/synthetic/{work_id}-p{i}.png" for i in range(2))

    def get_image_bytes(self, url):
        self.calls.append("image")
        if self.fail_images:
            raise OSError("injected image failure")
        self.started.set()
        if self.gate is not None:
            assert self.gate.wait(5), "synthetic source was not released"
        return png("blue" if "_p1" in url or "-p1" in url else "red")

    def close(self):
        self.closed = True


def terminal(jobs, job_id, expected="done"):
    with jobs._condition:
        assert jobs._condition.wait_for(lambda: any(j.job_id == job_id and
            j.state in {"done", "error", "stopped"} for j in jobs.snapshot()), timeout=8)
    found = next(j for j in jobs.snapshot() if j.job_id == job_id)
    assert found.state == expected, found.error_code
    return found


@pytest.mark.asyncio
async def test_explicit_original_save_library_restart_and_duplicate_reuse(tmp_path):
    source = FakeSource()
    root = tmp_path / "managed"
    services = ApplicationServices(live_client=source, pixiv_download_root=root)
    assert not source.calls, "opening the application must not read the remote account"
    try:
        assert services.library_snapshot().works == ()
        await services.refresh_bookmark_cache()
        candidates = services.download_candidates()
        assert len(candidates) == 1 and candidates[0].work_id == "202"
        job = await asyncio.to_thread(services.enqueue_managed_download, candidates[0], "first")
        result = await asyncio.to_thread(terminal, services.jobs, job.job_id)
        assert result.done == result.total == 2
        assert "original-pages" in source.calls and "regular-pages" not in source.calls
        snapshot = await services.refresh_library_snapshot()
        assert [w.work_id for w in snapshot.works] == ["202"]
        assert snapshot.authors[0].author_id == "23"
        assert services.bookmark_local_snapshot()[0].work_id == "202"
        provider = services.acquire_library_images()
        try:
            url = provider.url("202", 1, "view")
            assert "?catalog=" in url
            blob = await asyncio.to_thread(services.images.get_versioned, provider.token, "202", 1, "view")
            with Image.open(BytesIO(blob.data)) as decoded:
                assert decoded.getpixel((0, 0))[:3] == (0, 0, 255)
        finally:
            provider.close()
        before_calls = tuple(source.calls)
        duplicate = await asyncio.to_thread(services.enqueue_managed_download, candidates[0], "second")
        reused = await asyncio.to_thread(terminal, services.jobs, duplicate.job_id)
        assert reused.result == result.result and reused.total == reused.done == 2
        assert tuple(source.calls) == before_calls
        assert services.jobs.control(job.job_id, "delete")
        assert (root / result.result).is_file(), "deleting history must preserve verified outputs"
    finally:
        await asyncio.to_thread(services.close)
    assert source.closed
    second_source = FakeSource()
    reopened = ApplicationServices(live_client=second_source, pixiv_download_root=root)
    try:
        assert not second_source.calls and reopened.jobs._thread is None
        assert [w.work_id for w in reopened.library_snapshot().works] == ["202"]
        assert len(reopened.jobs.snapshot()) == 1
    finally:
        await asyncio.to_thread(reopened.close)


@pytest.mark.asyncio
async def test_two_client_enqueues_are_idempotent_and_snapshot_failure_keeps_old(tmp_path):
    source = FakeSource()
    source.gate = Event()
    services = ApplicationServices(live_client=source, pixiv_download_root=tmp_path / "managed")
    try:
        await services.refresh_bookmark_cache()
        record = services.download_candidates()[0]
        first = await asyncio.to_thread(services.enqueue_managed_download, record, "client-a")
        assert await asyncio.to_thread(source.started.wait, 5)
        second = await asyncio.to_thread(services.enqueue_managed_download, record, "client-b")
        resent = await asyncio.to_thread(services.enqueue_managed_download, record, "client-a")
        assert first.job_id == second.job_id == resent.job_id
        with pytest.raises(ValueError, match="selection changed"):
            await asyncio.to_thread(services.enqueue_managed_download, replace(record, title="stale"), "stale")
        source.gate.set()
        await asyncio.to_thread(terminal, services.jobs, first.job_id)
        await services.refresh_library_snapshot()
        old_snapshot = services.library_snapshot()
        old_remote = services.bookmark_remote_snapshot()
        pinned = services.acquire_library_images()
        try:
            source.fail = True
            with pytest.raises(RuntimeError, match="routes incomplete"):
                await services.refresh_bookmark_cache()
            assert services.library_snapshot() is old_snapshot
            assert services.bookmark_remote_snapshot() is old_remote
            assert services.images.get_versioned(pinned.token, "202", 0, "view").data
        finally:
            pinned.close()
    finally:
        source.gate.set()
        await asyncio.to_thread(services.close)


def test_invalid_storage_combinations_do_not_create_destinations(tmp_path):
    root = tmp_path / "absent"
    for extra in ({}, {"live_client": FakeSource(), "download_sandbox": tmp_path / "synthetic"},
                  {"live_client": FakeSource(), "learning_sandbox": tmp_path / "learning"},
                  {"live_client": FakeSource(), "library_readonly_db": tmp_path / "old.db",
                   "library_image_root": tmp_path / "old-images"}):
        with pytest.raises(ValueError):
            ApplicationServices(pixiv_download_root=root, **extra)
        assert not root.exists()


@pytest.mark.asyncio
async def test_failed_enqueue_does_not_publish_an_unaccepted_pin(tmp_path, monkeypatch):
    source = FakeSource()
    services = ApplicationServices(live_client=source, pixiv_download_root=tmp_path / "managed")
    try:
        await services.refresh_bookmark_cache()
        record = services.download_candidates()[0]
        def failure(*args, **kwargs):
            raise OSError("synthetic persistence failure")
        monkeypatch.setattr(services.jobs, "enqueue", failure)
        with pytest.raises(OSError):
            await asyncio.to_thread(services.enqueue_managed_download, record, "unaccepted")
        assert services._managed_job_records == {}
        assert services._resolve_managed_record(record.work_id) is None
        assert services.jobs.snapshot() == ()
    finally:
        await asyncio.to_thread(services.close)
    restarted_source = FakeSource()
    restarted = ApplicationServices(live_client=restarted_source, pixiv_download_root=tmp_path / "managed")
    try:
        assert restarted.jobs.snapshot() == ()
        assert restarted._managed_job_records == {}
        assert not restarted_source.calls, "unaccepted intents must not authorize automatic work"
    finally:
        await asyncio.to_thread(restarted.close)


@pytest.mark.asyncio
async def test_error_retry_after_process_restart_uses_durable_accepted_record(tmp_path):
    source = FakeSource()
    source.fail_images = True
    root = tmp_path / "managed"
    services = ApplicationServices(live_client=source, pixiv_download_root=root)
    try:
        await services.refresh_bookmark_cache()
        record = services.download_candidates()[0]
        job = await asyncio.to_thread(services.enqueue_managed_download, record, "accepted-before-failure")
        await asyncio.to_thread(terminal, services.jobs, job.job_id, "error")
        assert services.jobs.operation_ids(job.job_id) == ("accepted-before-failure",)
    finally:
        await asyncio.to_thread(services.close)
    new_source = FakeSource()
    reopened = ApplicationServices(live_client=new_source, pixiv_download_root=root)
    try:
        assert not new_source.calls and reopened.jobs._thread is None
        assert reopened.download_candidates() == ()
        assert reopened.jobs.snapshot()[0].state == "error"
        assert reopened.jobs.control(job.job_id, "retry")
        done = await asyncio.to_thread(terminal, reopened.jobs, job.job_id)
        assert done.attempt == 2 and done.done == done.total == 2
        assert not any(isinstance(call, tuple) and call[0] == "bookmarks" for call in new_source.calls)
        snapshot = await reopened.refresh_library_snapshot()
        assert snapshot.works[0].artwork.title == record.title
    finally:
        await asyncio.to_thread(reopened.close)


def test_managed_cli_check_is_side_effect_free_and_separates_credentials(tmp_path, capsys):
    cookie = tmp_path / "private" / "cookies.txt"
    root = tmp_path / "separate" / "downloads"
    args = ["--pixiv-cookie-file", str(cookie), "--pixiv-download-root", str(root)]
    assert parse_args(args).pixiv_download_root == root
    assert main(["--check", *args]) == 0
    assert json.loads(capsys.readouterr().out)["download_storage"] == "managed-pixiv"
    assert not cookie.exists() and not root.exists()
    for destination in (cookie.parent, cookie.parent / "downloads", tmp_path):
        with pytest.raises(SystemExit):
            parse_args(["--pixiv-cookie-file", str(cookie), "--pixiv-download-root", str(destination)])
    with pytest.raises(SystemExit):
        parse_args(["--pixiv-download-root", str(root)])
